typedef void* (*CopyFn)(const void* src);

typedef struct {
    void* data;          // Complex data pointer
    CopyFn deep_copier;  // Function pointer for custom copy logic
} PolyHandle;

// Concrete implementation for copying an integer payload
void* copy_int_payload(const void* src) {
    int* p_src = (int*)src;
    int* p_dst = malloc(sizeof(int));
    *p_dst = *p_src;
    return p_dst;
}

// Generic deep copy mechanism
PolyHandle deep_copy_handle(const PolyHandle* src) {
    PolyHandle dst;
    dst.deep_copier = src->deep_copier;
    // Execute custom copy logic via function pointer
    dst.data = src->deep_copier(src->data);
    return dst;
}
